er class="site-header"><div class="header-inner"><a class="brand" href="mainpage.php"><img src="../images/cal.png" alt="Appointment"><span>Appointment</span></a><nav><a href="mainpage.php">Panel</a><a class="active" href="showdoctorschedule.php">Doktor Programı</a></nav></div></header><main class="admin-wrap"><div class="page-head"><div><span class="eyebrow">DOKTOR YÖNETİMİ</span><h1>Doktor çalışma programı</h1><p>Doktorların klinik, gün ve saat bazındaki uygunluk kayıtlarını görüntüleyin.</p></div><a class="button secondary" href="adddoctorclinic.php">+ Program Ekle</a></div><section class="card table-card"><div class="table-top"><h2>Çalışma kayıtları</h2><span class="count"><?php echo $count;?> kayıt</span></div><?php if(!$count):?><div class="empty">Henüz doktor çalışma programı bulunmuyor.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Klinik</th><th>Doktor</th><th>Uzmanlık</th><th>Gün</th><th>Saat</th></tr></thead><tbody><?php while($r=$result->fetch_assoc()):?><tr><td><span class="clinic-name"><?php echo htmlspecialchars($r['ClinicName']??'Bilinmiyor');?></span><br><span class="muted"><?php echo htmlspecialchars($r['Town']??'');?></span></td><td class="doctor-name">Dr. <?php echo htmlspecialchars($r['DoctorName']??'Bilinmiyor');?></td><td class="muted"><?php echo htmlspecialchars($r['Specialization']??'-');?></td><td class="day"><?php echo htmlspecialchars($days[$r['Day']]??$r['Day']);?></td><td class="time"><?php echo htmlspecialchars(substr($r['Starttime'],0,5));?> – <?php echo htmlspecialchars(substr($r['Endtime'],0,5));?></td></tr><?php endwhile;?></tbody></table></div><?php $result=$conn->query($sql);?><div class="mobile-list"><?php while($r=$result->fetch_assoc()):?><article class="mobile-item"><div class="mobile-doctor">Dr. <?php echo htmlspecialchars($r['DoctorName']??'Bilinmiyor');?></div><div class="mobile-specialty"><?php echo htmlspecialchars($r['Specialization']??'-');?></div><div class="mobile-grid"><div><stron